package com.Senai.Mubak.controller; import jakarta.servlet.http.*; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import com.Senai.Mubak.model.*; import com.Senai.Mubak.service.UsuarioService; @Controller public class AuthController{final UsuarioService s; public AuthController(UsuarioService s){this.s=s;} @GetMapping("/cadastro") String c(Model m){m.addAttribute("usuarioForm",new UsuarioForm());return "auth/cadastro";} @PostMapping("/cadastro") String cp(@Valid @ModelAttribute UsuarioForm f,BindingResult b,Model m){if(b.hasErrors())return "auth/cadastro";try{s.cadastrar(f);return "redirect:/cadastro/sucesso";}catch(Exception e){m.addAttribute("erro",e.getMessage());return "auth/cadastro";}} @GetMapping("/cadastro/sucesso") String ok(){return "auth/sucesso";} @GetMapping("/login") String l(@RequestParam(required=false)String erro,Model m){m.addAttribute("erro",erro);return "auth/login";} @PostMapping("/login") String lp(@RequestParam String identificador,@RequestParam String senha,HttpSession h){try{Usuario u=s.login(identificador,senha);h.setAttribute("usuarioId",u.getId());h.setAttribute("perfil",u.getPerfil());return "redirect:/produtos";}catch(Exception e){return "redirect:/login?erro=Login+inválido";}} @PostMapping("/logout") String lo(HttpSession h){h.invalidate();return "redirect:/login";}}